    {mediaRequest === "requested" && <div className="meet-media-notice" role="status"><div><ShieldCheck size={18} /><span><strong>{activeMode} request sent</strong><small>Text stays on while Zoya chooses. Your microphone and camera remain off until they explicitly accept.</small></span></div><button onClick={() => chooseMode("Text")}>Cancel request</button></div>}
