  return <aside className="pro-panel" aria-label="CONFLUX Pro"><button className="close-pro" onClick={onClose} aria-label="Close Pro details"><PanelLeftClose size={21} /></button><p className="time-stamp">CONFLUX PRO</p><h2>When a connection<br />needs more room.</h2><p>Pro is for the moment you know what you’re looking for—or you are ready to turn a good conversation into work.</p><div className="pro-outcomes"><div><Search size={19} /><span><strong>Find someone specific</strong><small>Use intent, skill, build-stage and availability filters.</small></span></div><div><Video size={19} /><span><strong>Keep the conversation going</strong><small>Use extended sessions and screen sharing.</small></span></div><div><BriefcaseBusiness size={19} /><span><strong>Build together</strong><small>Create focused Build Rooms with memory and next steps.</small></span></div></div><div className="price-block"><span>India-first launch test</span><strong>₹199–₹399 <small>/ month</small></strong><p>Illustrative range from the product plan; checkout remains server-verified.</p></div><button className="primary-button" onClick={() => { onClose(); onToast("Checkout would resume this exact intent after secure payment confirmation."); }}>See Pro when you need it <ArrowRight size={18} /></button><small className="pro-footnote">Free networking and contact sharing stay free.</small></aside>;
